r"""重新總計：叫 PCCES 4.3 自己的 DLL（x86 宿主 RecalcHost.exe）在資料庫裡重算一本預算書，等於畫面上按「重新總計」。

這是專案唯一寫 PCCES 資料庫的地方（CLAUDE.md 規則 1 的例外）。Python 這邊不發任何 SQL：寫入全在宿主裡經
PCCES 自己的 ItemCalculate.CalculateAll；拒跑的核對也在宿主裡做（PCCES 版本與組件雜湊、方法簽章、工程在不在、
舊算法、BudProjEditUser 鎖定、這台有沒有 PccesMain 在跑），check 模式只讀。這裡只負責找安裝資料夾與宿主、
起子行程（MCP server 是 64 位元，PCCES 的 DLL 只能在 x86／CLR 2 載入）、把退出碼翻成使用者的下一步。
宿主原始碼與建置在 tools\recalc_host\，驗收探針在 tools\recalc_probe\probe.py。
"""

from __future__ import annotations

import os
import shutil
import subprocess
import tempfile
import time
from dataclasses import dataclass, field
from decimal import Decimal, InvalidOperation
from pathlib import Path

# 退出碼，跟 tools\recalc_host\RecalcHost.cs 一一對應
EXIT_OK, EXIT_USAGE, EXIT_SETUP, EXIT_OLD_CALC, EXIT_CALC_FAILED, EXIT_EDITING = 0, 2, 3, 4, 5, 6
EXIT_VERSION, EXIT_SIGNATURE, EXIT_CRASH, EXIT_NOT_FOUND, EXIT_PCCES_RUNNING, EXIT_NOT_ALLOWED = 7, 8, 9, 10, 11, 12

# 實案（詳細表 3721 列）一次約 14 秒；Codex 的工具預設 300 秒逾時，留在它之內
HOST_TIMEOUT = 240
DEFAULT_INSTALL = Path(r"C:\Program Files (x86)\PccesWin4.3")
# 測試與探針用：限定只准重新總計這幾個工程（逗號分隔），宿主也照這個變數再擋一次。產品不設
ALLOW_ENV = "PCX_RECALC_ALLOW"

_HERE = Path(__file__).resolve()
# 開發時 src\pcx_mcp\recalc.py 往上兩層是專案資料夾；plugin 裡是 <plugin>\python\Lib\site-packages\pcx_mcp\recalc.py
PROJECT_ROOT = _HERE.parents[2]
PLUGIN_ROOT = _HERE.parents[4] if len(_HERE.parents) > 4 else _HERE.parent
BUILD_HINT = r"uv run python -X utf8 tools\recalc_host\build_host.py"

_SYNC = "跟 PCCES 畫面上按「重新總計」同一套"
_FALLBACK = "請使用者在 PCCES 打開這本預算書，按工具列的「重新總計」。"


class RecalcError(Exception):
    """拒跑或失敗。訊息是使用者的下一步；written=True 表示宿主已經開始寫，預算書可能只算了一部分。"""

    def __init__(self, message: str, *, written: bool = False):
        super().__init__(message)
        self.written = written


class RecalcNotFound(LookupError):
    """宿主在資料庫裡找不到這個工程代碼（server 端另查可選代碼）。"""

    def __init__(self, code: str):
        super().__init__(code)
        self.code = code


@dataclass
class HostRun:
    rc: int
    lines: list[list[str]]
    wall: float

    def get(self, key: str) -> list[str] | None:
        return next((ln[1:] for ln in self.lines if ln[0] == key), None)

    def all(self, key: str) -> list[list[str]]:
        return [ln[1:] for ln in self.lines if ln[0] == key]

    def value(self, key: str) -> str | None:
        v = self.get(key)
        return v[0] if v else None

    @property
    def written(self) -> bool:
        return any(v[:1] == ["write_begin"] for v in self.all("stage"))


@dataclass
class RecalcResult:
    code: str
    name: str
    before: Decimal | None
    after: Decimal | None
    wall: float
    ms_calculate: int | None
    pcces_version: str
    database: str
    memo_rows: tuple[int, int]
    warnings: list[str] = field(default_factory=list)


# ---------- 找安裝資料夾與宿主 ----------


def _registry_install_dirs() -> list[Path]:
    """登錄檔解除安裝清單裡 DisplayName 是 PccesWin… 的 InstallLocation（tools\\啟動PCCES給電腦控制.ps1 同一套找法）。"""
    try:
        import winreg
    except ImportError:  # 非 Windows
        return []
    out: list[Path] = []
    roots = (r"SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall",
             r"SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall")
    for root in roots:
        try:
            key = winreg.OpenKey(winreg.HKEY_LOCAL_MACHINE, root)
        except OSError:
            continue
        with key:
            i = 0
            while True:
                try:
                    sub = winreg.EnumKey(key, i)
                except OSError:
                    break
                i += 1
                try:
                    with winreg.OpenKey(key, sub) as s:
                        name = str(winreg.QueryValueEx(s, "DisplayName")[0])
                        loc = str(winreg.QueryValueEx(s, "InstallLocation")[0])
                except OSError:
                    continue
                if name.startswith("PccesWin") and loc.strip():
                    out.append(Path(loc.strip().rstrip("\\")))
    return out


def install_dir() -> Path:
    """PCCES 安裝資料夾：環境變數 PCX_PCCES_DIR（測試用）＞登錄檔＞預設位置；要有 PccesMain.exe 才算。"""
    env = os.environ.get("PCX_PCCES_DIR")
    cands = [Path(env)] if env else [*_registry_install_dirs(), DEFAULT_INSTALL]
    for d in cands:
        if (d / "PccesMain.exe").is_file():
            return d
    where = "、".join(dict.fromkeys(str(d) for d in cands))
    raise RecalcError(f"這台電腦找不到 PCCES 4.3（找過 {where}，都沒有 PccesMain.exe）。"
                      "重新總計要在裝了 PCCES 的電腦上跑；沒裝的話請使用者在裝 PCCES 的那台按「重新總計」。")


def host_path() -> Path:
    """宿主 exe：環境變數 PCX_RECALC_HOST（測試、探針換變體用）＞開發專案 tmp\\recalc_host\\＞plugin 的 recalc_host\\。"""
    env = os.environ.get("PCX_RECALC_HOST")
    if env:
        p = Path(env)
    elif (PROJECT_ROOT / "pyproject.toml").is_file():
        p = PROJECT_ROOT / "tmp" / "recalc_host" / "RecalcHost.exe"
        if not p.is_file():
            raise RecalcError(f"開發環境還沒編重新總計的宿主程式（{p}）。請在專案根目錄跑 {BUILD_HINT} 再叫一次。")
    else:
        p = PLUGIN_ROOT / "recalc_host" / "RecalcHost.exe"
    if not p.is_file():
        raise RecalcError(f"找不到重新總計的宿主程式 {p}。plugin 可能沒裝完整，請使用者雙擊 plugin 的「更新.bat」或重新安裝。")
    return p


def host_command(mode: str, code: str, install: Path) -> list[str]:
    """起宿主的命令列；測試把它換成假宿主（不必有 PCCES 與 .NET 3.5）。"""
    return [str(host_path()), mode, code, str(install)]


# ---------- 起宿主、解析輸出 ----------


def parse_output(data: bytes) -> list[list[str]]:
    return [ln.split("\t") for ln in data.decode("utf-8", "replace").splitlines() if ln.strip()]


def run_host(mode: str, code: str, timeout: float | None = None) -> HostRun:
    install = install_dir()
    cmd = host_command(mode, code, install)
    # 工作資料夾每次另開、跑完刪掉：PCCES 的 DLL 若往目前資料夾寫東西，不會落在 plugin 快取或安裝資料夾
    work = Path(tempfile.mkdtemp(prefix="pcx_recalc_"))
    flags = getattr(subprocess, "CREATE_NO_WINDOW", 0)  # MCP server 沒有主控台時，不讓宿主自己開一個黑窗
    t0 = time.perf_counter()
    try:
        p = subprocess.run(cmd, capture_output=True, cwd=str(work), timeout=timeout or HOST_TIMEOUT,
                           creationflags=flags, stdin=subprocess.DEVNULL)
    except subprocess.TimeoutExpired as exc:
        run = HostRun(-1, parse_output(exc.stdout or b""), time.perf_counter() - t0)
        sec = timeout or HOST_TIMEOUT
        if run.written:
            raise RecalcError(
                f"重新總計超過 {sec:.0f} 秒還沒做完，已中止宿主程式；中止前已經開始寫入資料庫，"
                "中途中止的後果沒有測過，這本預算書可能只算了一部分。" + _FALLBACK + "按完再用 pcces_read_db_budget 看總價。",
                written=True) from exc
        raise RecalcError(f"重新總計的核對超過 {sec:.0f} 秒還沒做完，已中止宿主程式，還沒開始寫入。"
                          "請使用者確認 SQL Server（SQLEXPRESS）服務正常、PCCES 能開預算書，再叫一次。") from exc
    except OSError as exc:
        raise RecalcError(f"重新總計的宿主程式起不來（{exc}）。它要 .NET Framework 3.5（PCCES 本身也要），"
                          "請使用者確認 PCCES 能正常開啟。") from exc
    finally:
        shutil.rmtree(work, ignore_errors=True)
    return HostRun(p.returncode, parse_output(p.stdout), time.perf_counter() - t0)


def _allowed(code: str) -> bool:
    allow = os.environ.get(ALLOW_ENV)
    return not allow or code.strip().lower() in {a.strip().lower() for a in allow.split(",")}


def _not_allowed(code: str) -> str:
    return (f"環境變數 {ALLOW_ENV} 只放行 {os.environ.get(ALLOW_ENV) or '（宿主那邊設的）'}，工程 {code} 不在裡面，"
            "沒有寫入任何東西（這個變數是測試用來限制可寫工程的）。")


def _dec(v: str | None) -> Decimal | None:
    if v is None or v == "":
        return None
    try:
        return Decimal(v)
    except InvalidOperation:
        return None


def _editors(rows: list[list[str]]) -> str:
    out = []
    for r in rows:
        uid, name, start = (r + ["", "", ""])[:3]
        out.append(f"{name or uid}（帳號 {uid}，{start or '時間不明'} 起）")
    return "、".join(out) or "（沒有列出鎖定者）"


def explain(run: HostRun, code: str) -> RecalcError | RecalcNotFound:
    """非 0 的退出碼翻成給使用者的話；版本、簽章、拒跑原因都從宿主的輸出取。"""
    pc = (run.get("project") or [code])[0]
    rc = run.rc
    if rc == EXIT_NOT_FOUND:
        return RecalcNotFound(code)
    if rc == EXIT_VERSION:
        bad = []
        v = run.get("pcces_version")
        if v and v[1] != "ok":
            bad.append(f"PCCES 版本是 {v[0]}，驗證過的是 {v[2]}")
        for f in run.all("file"):
            if f[1] == "missing":
                bad.append(f"少了 {f[0]}")
            elif f[1] != "ok":
                bad.append(f"{f[0]} 的內容跟驗證過的不同")
        return RecalcError("這台 PCCES 跟驗證過的版本不同，沒有寫入任何東西：" + "；".join(bad or ["（宿主沒說哪裡不同）"]) + "。"
                           "重新總計靠 PCCES 內部的 DLL，換版後要先重跑驗收、確認結果跟畫面相同才能放行，"
                           "請使用者回報維護這個工具的人；在那之前" + _FALLBACK)
    if rc == EXIT_SIGNATURE:
        miss = [s[0] for s in run.all("sig") if s[1:2] != ["ok"]]
        err = run.get("sig_error")
        what = "、".join(miss) if miss else (f"{err[0]}：{err[1]}" if err else "（宿主沒說是哪一個）")
        return RecalcError(f"這台 PCCES 的內部方法跟驗證過的不同（{what}），沒有寫入任何東西。"
                           "請使用者回報維護這個工具的人；在那之前" + _FALLBACK)
    if rc == EXIT_OLD_CALC:
        return RecalcError(f"工程 {pc} 用的是 PCCES 的舊算法（pubProject.enableNewCalculateCost=0），"
                           "這支工具只接了新算法（ItemCalculate.CalculateAll）那一路，沒有寫入任何東西。" + _FALLBACK)
    if rc == EXIT_EDITING:
        return RecalcError(f"PCCES 記錄工程 {pc} 正被鎖定編輯中：{_editors(run.all('editor'))}，沒有寫入任何東西。"
                           "PCCES 開著同一本時重新總計，畫面存檔可能用舊值蓋回去。請使用者在 PCCES 關掉這本預算書再叫一次，"
                           "或直接在 PCCES 畫面按「重新總計」。PCCES 根本沒開著這本的話，是上次沒正常關閉留下的鎖定紀錄"
                           "（BudProjEditUser），這支工具不會自己清，請使用者回報。")
    if rc == EXIT_PCCES_RUNNING:
        pids = "、".join(p[0] for p in run.all("pcces_process"))
        return RecalcError(f"這台電腦的 PCCES 正在執行（PccesMain，PID {pids}），沒有寫入任何東西。"
                           "PCCES 開預算書時不一定會在資料庫留下紀錄（單一編輯鎖定預設關著），分不出它開著哪一本；"
                           "開著同一本時重新總計，畫面存檔可能用舊值蓋回去。請使用者先把 PCCES 整個關掉再叫一次，"
                           "或直接在 PCCES 畫面按「重新總計」。")
    if rc == EXIT_NOT_ALLOWED:
        return RecalcError(_not_allowed(pc))
    if rc == EXIT_SETUP:
        s = run.get("setup") or ["", ""]
        if s[0] == "no_connection_string":
            return RecalcError("PCCES 的設定檔 PccesMain.exe.config 沒有 Pcces 的連線字串，沒有寫入任何東西。"
                               "請使用者確認 PCCES 能正常開預算書（ConfigEditor 設過資料庫）。")
        return RecalcError(f"PCCES 安裝資料夾 {s[1] if len(s) > 1 else ''} 少了 PccesMain.exe 或 PccesMain.exe.config，沒有寫入任何東西。")
    if rc == EXIT_CALC_FAILED:
        c = run.get("calc") or ["?", ""]
        return RecalcError(f"PCCES 的重新總計回報失敗（ReturnCode {c[0]}：{c[1] if len(c) > 1 else ''}）。"
                           "說明項歸零與發包權限同步已經寫入，詳細表可能只算了一部分。"
                           + _FALLBACK + "PCCES 會顯示它自己的錯誤訊息。", written=True)
    exc = run.get("exception")
    stage = [s[0] for s in run.all("stage")]
    detail = exc[0][:600] if exc else f"退出碼 {rc}，輸出最後幾行：{' / '.join(chr(9).join(ln) for ln in run.lines[-5:])}"
    if run.written and "done" not in stage:
        return RecalcError(f"重新總計的宿主程式在寫入途中出錯（做到 {stage[-1]}）：{detail}。"
                           "這本預算書可能只算了一部分。" + _FALLBACK, written=True)
    return RecalcError(f"重新總計的宿主程式出錯，還沒開始寫入：{detail}")


def recalc(code: str, *, timeout: float | None = None) -> RecalcResult:
    """重新總計一本預算書；拒跑或失敗丟 RecalcError／RecalcNotFound。"""
    code = (code or "").strip()
    if not code:
        raise RecalcError("project_code 不能是空的；先叫 pcces_list_db_budgets 看有哪些工程代碼。")
    if not _allowed(code):
        raise RecalcError(_not_allowed(code))
    run = run_host("recalc", code, timeout)
    if run.rc != EXIT_OK:
        raise explain(run, code)
    if run.value("stage") is None or [s[0] for s in run.all("stage")][-1] != "done":
        raise RecalcError("重新總計的宿主程式回報成功，卻沒有做完全部步驟的紀錄；預算書可能只算了一部分。" + _FALLBACK, written=True)
    proj = run.get("project") or [code, ""]
    memo = (run.value("memo_itemA_rows") or "0", run.value("memo_mrsA_rows") or "0")
    warnings = []
    opened = {p[0] for p in run.all("pcces_process_after")} - {p[0] for p in run.all("pcces_process")}
    if run.all("editor_after") or opened:
        warnings.append("重新總計期間 PCCES 被打開了：畫面上若開著這本預算書，看到的可能還是舊值，存檔可能蓋回舊值。"
                        "請使用者在 PCCES 關掉這本預算書重開，必要時在畫面上再按一次「重新總計」。")
    unpinned = [u[0] for u in run.all("unpinned")]
    if unpinned:
        warnings.append(f"重新總計用到了沒核對過內容的 PCCES 組件（{'、'.join(unpinned)}），這個組合沒有驗證過；"
                        "請使用者在 PCCES 畫面上再按一次「重新總計」確認總價相同，並回報維護這個工具的人。")
    db = run.get("database") or ["", ""]
    ms = run.value("ms_calculate")
    return RecalcResult(
        code=proj[0], name=proj[1] if len(proj) > 1 else "",
        before=_dec(run.value("projamt_before")), after=_dec(run.value("projamt_after")),
        wall=run.wall, ms_calculate=int(ms) if ms and ms.isdigit() else None,
        pcces_version=(run.get("pcces_version") or ["?"])[0],
        database="／".join(x for x in db[:2] if x),
        memo_rows=(int(memo[0]) if memo[0].isdigit() else 0, int(memo[1]) if memo[1].isdigit() else 0),
        warnings=warnings,
    )
